/** Generate monthly periods between two dates: how many were made, or null when refused. */
export async function generatePeriods(page: Page, from: string, to: string): Promise<number | null> {
  await page.getByTestId('period-generate-from').fill(from);
  await page.getByTestId('period-generate-to').fill(to);
  const was = await shown(page.getByTestId('period-generated'));
  await page.getByTestId('period-generate').click();
  await page.waitForTimeout(300);
  const ok = await until(page, async () => (await page.getByTestId('period-generated').count()) > 0
    && (await shown(page.getByTestId('period-generated'))) !== '' && ((await shown(page.getByTestId('period-generated'))) !== was || was === ''),
    page.getByTestId('period-generate-error'), 'generate periods');
  return ok ? Number(await shown(page.getByTestId('period-generated'))) : null;
}

/** close | soft-close | reopen | lock | unlock: true when the period's closed (or locked) flag changed. */
export async function periodAction(page: Page, name: string, action: string): Promise<boolean> {
  const r = page.getByTestId(`period-row-${name}`);
  const cell = action === 'lock' || action === 'unlock' ? 'period-locked' : 'period-closed';
  const was = await shown(r.getByTestId(cell));
  await r.getByTestId(`period-${action}`).click();
  return until(page, async () => await shown(r.getByTestId(cell)) !== was,
    r.getByTestId('period-error'), `period ${action}`);
}

export async function setSetting(page: Page, key: string, value: string): Promise<void> {
  await page.getByTestId(`setting-${key}`).fill(value);
  await page.getByTestId('settings-save').click();
  await expect(page.getByTestId(`setting-${key}-current`)).toHaveText(value, { timeout: WAIT });
}

/** Save a setting where the screen may refuse it: true when the value in force shows it. */
export async function setSettingTry(page: Page, key: string, value: string): Promise<boolean> {
  const done = async () => (await shown(page.getByTestId(`setting-${key}-current`))) === value;
  const already = await done();
  await page.getByTestId(`setting-${key}`).fill(value);
  await page.getByTestId('settings-save').click();
  return until(page, done, page.getByTestId('settings-error'), 'save setting', already);
}

/** Save a setting from a date; `shows` is the value in force on the sheet's today once saved
 *  (a from-date after today leaves the current value as it was). */
export async function setSettingDated(page: Page, key: string, value: string, from: string, shows: string): Promise<boolean> {
  const done = async () => (await shown(page.getByTestId(`setting-${key}-current`))) === shows
    && !(await page.getByTestId('settings-error').isVisible().catch(() => false));
  const already = await done();
  await page.getByTestId(`setting-${key}`).fill(value);
  await page.getByTestId(`setting-${key}-from`).fill(from);
  await page.getByTestId('settings-save').click();
  const ok = await until(page, done, page.getByTestId('settings-error'), 'save dated setting', already);
  if (ok) await page.waitForTimeout(300);     // the value may already have shown; let the save land
  return ok;
}

/** Save a claim template: true once its row shows the amount and note. */
export async function saveTemplate(page: Page, f: { name: string; amount: string; note: string }): Promise<boolean> {
import { Component, effect, inject, signal, untracked } from '@angular/core';
import { FLOOR, LIMIT, ROLES, TERMS, RoleName, RoleView, SettingsApi } from '../../core/settings';
import { Session } from '../../core/session';

// The sheet's settings (the clerk limit and the floor) and the roles user names have on it (clerk by default,
// or steward), each changed through its own form.
@Component({
  selector: 'app-settings',
  template: `
    <section aria-labelledby="settings-heading">
      <h2 id="settings-heading">Settings</h2>
      <form (submit)="saveSettings($event)" aria-label="Change settings">
        <label for="setting-clerk-limit">Clerk limit (empty: no limit)</label>
        <input
          id="setting-clerk-limit"
          data-testid="setting-clerk-limit"
          inputmode="decimal"
          [value]="limit()"
          (input)="limit.set(value($event)); limitEdited = true; settingsError.set(null)"
        />
        <label for="setting-floor">Floor</label>
        <input
          id="setting-floor"
          data-testid="setting-floor"
          inputmode="decimal"
          [value]="floorInput()"
          (input)="floorInput.set(value($event)); floorEdited = true; settingsError.set(null)"
        />
        <label for="setting-terms">Terms (days)</label>
        <input
          id="setting-terms"
          data-testid="setting-terms"
          inputmode="numeric"
          [value]="termsInput()"
          (input)="termsInput.set(value($event)); termsEdited = true; settingsError.set(null)"
        />
        <button type="submit" data-testid="settings-save">Save settings</button>
        @if (settingsError(); as message) {
          <p role="alert" data-testid="settings-error">{{ message }}</p>
        }
      </form>
      <p>Clerk limit in force: <span data-testid="setting-clerk-limit-current">{{ clerkLimit() ?? '' }}</span></p>
      <p>Floor in force: <span data-testid="setting-floor-current">{{ session.floor() }}</span></p>
      <p>Terms in force: <span data-testid="setting-terms-current">{{ session.terms() }}</span></p>
      <h3>Roles</h3>
      <form (submit)="saveRole($event)" aria-label="Set a role">
        <label for="role-form-user">User</label>
        <input
          id="role-form-user"
          data-testid="role-form-user"
          [value]="roleUser()"
          (input)="roleUser.set(value($event)); roleError.set(null)"
        />
        <label for="role-form-role">Role ({{ roleNames }})</label>
        <input
          id="role-form-role"
          data-testid="role-form-role"
          [value]="roleName()"
          (input)="roleName.set(value($event)); roleError.set(null)"
        />
        <button type="submit" data-testid="role-form-submit">Set role</button>
        @if (roleError(); as message) {
          <p role="alert" data-testid="role-form-error">{{ message }}</p>
        }
      </form>
      <table>
        <caption>Roles set (any other name is a clerk)</caption>
        <thead>
          <tr>
            <th scope="col">User</th>
            <th scope="col">Role</th>
          </tr>
        </thead>
        <tbody>
          @for (r of roles(); track r.user) {
            <tr [attr.data-testid]="'role-row-' + r.user">
              <th scope="row">{{ r.user }}</th>
              <td data-testid="role-value">{{ r.role }}</td>
            </tr>
          }
        </tbody>
      </table>
    </section>
  `,
})
export class Settings {
  protected readonly session = inject(Session);
  private readonly api = inject(SettingsApi);

  protected readonly roleNames = ROLES.join(' or ');
  protected readonly clerkLimit = signal<string | null>(null);
  protected readonly roles = signal<RoleView[]>([]);
  protected readonly limit = signal('');
  protected readonly floorInput = signal('');
  protected readonly termsInput = signal('');
  /** Which settings were typed into since the last save: a save changes only those. */
  protected limitEdited = false;
  protected floorEdited = false;
  protected termsEdited = false;
  protected readonly roleUser = signal('');
  protected readonly roleName = signal('');
  protected readonly settingsError = signal<string | null>(null);
  protected readonly roleError = signal<string | null>(null);
  /** A submit is waiting for its answer: a second submit meanwhile is ignored. */
  private busy = false;

  constructor() {
    // Every sheet load re-reads the sheet's settings and roles from the store.
    effect(() => {
      const sheet = this.session.sheet();
      const loads = this.session.loads();
      untracked(() => {
        this.clerkLimit.set(null);
        this.roles.set([]);
        this.settingsError.set(null);
        this.roleError.set(null);
        if (sheet) void this.reload(sheet, loads);
      });
    });
  }

  protected value(event: Event): string {
    return (event.target as HTMLInputElement).value;
  }

  protected async saveSettings(event: Event): Promise<void> {
    event.preventDefault();
    if (this.busy) return;
    this.settingsError.set(null);
    const sheet = this.session.sheet();
    if (!sheet) return;
    const limit = this.limit().trim();
    const floor = this.floorInput().trim();
    // With nothing typed since the last save, saving sets the clerk limit again as it stands.
    const terms = this.termsInput().trim();
    const saveLimit = this.limitEdited || (!this.floorEdited && !this.termsEdited);
    const saveFloor = this.floorEdited;
    const saveTerms = this.termsEdited;
    if (saveLimit && !LIMIT.test(limit)) {
      this.settingsError.set('Type a clerk limit of 0.00 or more, with up to two decimals, or leave it empty for no limit.');
      return;
    }
    if (saveFloor && !FLOOR.test(floor)) {
      this.settingsError.set('Type a floor of 0.00 or more, with up to two decimals.');
      return;
    }
    if (saveTerms && !TERMS.test(terms)) {
      this.settingsError.set('Type terms as a whole number of days.');
      return;
    }
    this.busy = true;
    try {
      if (saveLimit) {
        const view = await this.api.setClerkLimit(sheet, limit);
        this.clerkLimit.set(view.clerkLimit);
        this.limitEdited = false;
      }
      if (saveFloor) {
        const view = await this.api.setFloor(sheet, floor);
        this.session.floor.set(view.floor);
        this.floorEdited = false;
      }
      if (saveTerms) {
        const view = await this.api.setTerms(sheet, terms);
        this.session.terms.set(view.terms);
        this.termsEdited = false;
      }
    } catch {
      this.settingsError.set('The settings could not be saved.');
    } finally {
      this.busy = false;
    }
  }

  protected async saveRole(event: Event): Promise<void> {
    event.preventDefault();
    if (this.busy) return;
    this.roleError.set(null);
    const sheet = this.session.sheet();
    if (!sheet) return;
    const user = this.roleUser().trim();
    const role = this.roleName().trim();
    if (!user) {
      this.roleError.set('Type the user name to set a role for.');
      return;
    }
    if (!(ROLES as readonly string[]).includes(role)) {
      this.roleError.set(`A role is ${this.roleNames}.`);
      return;
    }
    this.busy = true;
    try {
      const saved = await this.api.setRole(sheet, { user, role: role as RoleName });
      this.roles.update((all) =>
        [...all.filter((r) => r.user !== saved.user), saved].sort((a, b) => a.user.localeCompare(b.user)),
      );
      this.roleUser.set('');
      this.roleName.set('');
    } catch {
      this.roleError.set(`The role of ${user} could not be set.`);
    } finally {
      this.busy = false;
    }
  }

  private async reload(sheet: string, loads: number): Promise<void> {
    const [settings, roles] = await Promise.all([this.api.get(sheet), this.api.roles(sheet)]);
    // A later load may have started while this one was in flight: only the latest is shown.
    if (this.session.sheet() === sheet && this.session.loads() === loads) {
      this.clerkLimit.set(settings.clerkLimit);
      this.session.floor.set(settings.floor);
      this.session.terms.set(settings.terms);
      this.roles.set(roles);
    }
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';

/** The roles a user name can have on a sheet; a name with none set is a clerk. */
export const ROLES = ['clerk', 'steward'] as const;
export type RoleName = (typeof ROLES)[number];

export interface RoleView {
  user: string;
  role: RoleName;
}

export interface SettingsView {
  /** The clerk limit with two decimals, e.g. "1.50"; null when there is no limit. */
  clerkLimit: string | null;
  /** The floor with two decimals, e.g. "1.00": a claim's live due is at least it. */
  floor: string;
  /** The terms in days: a claim is due by its date plus them. */
  terms: number;
}

/** A clerk limit as the form takes it: up to two decimals, or blank for no limit. */
export const LIMIT = /^(\d{1,12}(\.\d{1,2})?)?$/;

/** A floor as the form takes it: 0.00 or more, with up to two decimals. */
export const FLOOR = /^\d{1,12}(\.\d{1,2})?$/;

/** Terms as the form takes them: a whole number of days. */
export const TERMS = /^\d{1,4}$/;

// The sheet's settings and the roles its user names have, read from and written to the store.
@Injectable({ providedIn: 'root' })
export class SettingsApi {
  private readonly http = inject(HttpClient);

  get(sheet: string): Promise<SettingsView> {
    return firstValueFrom(this.http.get<SettingsView>(`${this.url(sheet)}/settings`));
  }

  /** Set the clerk limit; a blank value means no limit. */
  setClerkLimit(sheet: string, value: string): Promise<SettingsView> {
    return firstValueFrom(this.http.put<SettingsView>(`${this.url(sheet)}/settings/clerk-limit`, { value }));
  }

  /** Set the floor. */
  setFloor(sheet: string, value: string): Promise<SettingsView> {
    return firstValueFrom(this.http.put<SettingsView>(`${this.url(sheet)}/settings/floor`, { value }));
  }

  /** Set the terms, in days. */
  setTerms(sheet: string, value: string): Promise<SettingsView> {
    return firstValueFrom(this.http.put<SettingsView>(`${this.url(sheet)}/settings/terms`, { value }));
  }

  /** The roles set on the sheet, by user name. */
  roles(sheet: string): Promise<RoleView[]> {
    return firstValueFrom(this.http.get<RoleView[]>(`${this.url(sheet)}/roles`));
  }

  /** Set a user name's role on the sheet. */
  setRole(sheet: string, form: RoleView): Promise<RoleView> {
    return firstValueFrom(this.http.put<RoleView>(`${this.url(sheet)}/roles`, form));
  }

  private url(sheet: string): string {
    return `/api/sheets/${encodeURIComponent(sheet)}`;
  }
}

