import { HttpErrorResponse } from '@angular/common/http';
import { Component, inject, input, output, signal } from '@angular/core';
import { AMOUNT, ClaimAction, ClaimView, ClaimsApi, cents, dueBy, money, overdue } from '../../core/claims';
import { Grade } from '../../core/people';
import { PeriodView, periodOn } from '../../core/periods';
import { NO_RATE, RateView, claimDueCents } from '../../core/rates';
import { Session } from '../../core/session';

// A person's claims: listed newest first, added and edited through one form on the person's row,
// and moved through their statuses (open, settle, void) from each claim's row.
const PAST: Record<ClaimAction, string> = { open: 'opened', settle: 'settled', void: 'voided' };

@Component({
  selector: 'app-claims',
  template: `
    <form (submit)="save($event)" [attr.aria-label]="(editing() === null ? 'Add a claim for ' : 'Edit a claim of ') + personName()">
      <label [for]="'claim-form-amount-' + personId()">Amount</label>
      <input
        [id]="'claim-form-amount-' + personId()"
        data-testid="claim-form-amount"
        inputmode="decimal"
        [value]="amount()"
        (input)="amount.set(value($event)); error.set(null)"
      />
      <label [for]="'claim-form-date-' + personId()">Date</label>
      <input
        [id]="'claim-form-date-' + personId()"
        type="date"
        data-testid="claim-form-date"
        [value]="date()"
        (input)="date.set(value($event)); error.set(null)"
      />
      <label [for]="'claim-form-note-' + personId()">Note</label>
      <input
        [id]="'claim-form-note-' + personId()"
        data-testid="claim-form-note"
        [value]="note()"
        (input)="note.set(value($event)); error.set(null)"
      />
      <button type="submit" data-testid="claim-form-submit">
        {{ editing() === null ? 'Add claim' : 'Save claim' }}
      </button>
      @if (editing() !== null) {
        <button type="button" data-testid="claim-form-cancel" (click)="reset()">Cancel</button>
      }
      @if (error(); as message) {
        <p role="alert" data-testid="claim-form-error">{{ message }}</p>
      }
    </form>
    <ul [attr.aria-label]="'Claims of ' + personName()">
      @for (c of claims(); track c.id) {
        <li [attr.data-testid]="'claim-row-' + c.id">
          <span>No. <span data-testid="claim-number">{{ c.number ?? '' }}</span></span>
          <span data-testid="claim-amount">{{ c.amount }}</span>
          <span data-testid="claim-date">{{ c.date }}</span>
          <span data-testid="claim-note">{{ c.note }}</span>
          <span>Due <span data-testid="claim-due">{{ dueOf(c) }}</span></span>
          <span>Due by <span data-testid="claim-due-by">{{ dueByOf(c) }}</span></span>
          <span>Overdue <span data-testid="claim-overdue">{{ overdueOf(c) ? 'yes' : 'no' }}</span></span>
          <span>Period <span data-testid="claim-period">{{ periodOf(c) }}</span></span>
          <span data-testid="claim-status">{{ c.status }}</span>
          <span>Stated <span data-testid="claim-stated">{{ c.stated ? 'yes' : 'no' }}</span></span>
          <span>Opened by <span data-testid="claim-opened-by">{{ c.openedBy ?? '' }}</span></span>
          <button
            type="button"
            data-testid="claim-edit"
            [attr.aria-label]="'Edit claim of ' + c.amount + ' on ' + c.date"
            (click)="open(c)"
          >
            Edit
          </button>
          @for (a of actions; track a.action) {
            <button
              type="button"
              [attr.data-testid]="'claim-' + a.action"
              [attr.aria-label]="a.label + ' claim of ' + c.amount + ' on ' + c.date"
              (click)="act(c, a.action)"
            >
              {{ a.label }}
            </button>
  /** The sheet's rates; each claim uses the one its person's grade has in force on its date. */
  readonly rates = input.required<RateView[]>();
  /** The sheet's periods; each claim belongs to the one whose dates contain its date, or to none. */
  readonly periods = input.required<PeriodView[]>();
  /** A claim added or saved through the form. */
  readonly saved = output<ClaimView>();

  protected readonly amount = signal('');
  protected readonly date = signal('');
  protected readonly note = signal('');
  /** The id of the claim open in the form, or null when the form adds a new claim. */
  protected readonly editing = signal<number | null>(null);
  protected readonly error = signal<string | null>(null);
  /** A submit is waiting for its answer: a second submit meanwhile is ignored. */
  private busy = false;
  /** The refusal of the last action taken on a claim's row, shown on that row. */
  protected readonly claimError = signal<{ id: number; message: string } | null>(null);
  protected readonly actions: { action: ClaimAction; label: string }[] = [
    { action: 'open', label: 'Open' },
    { action: 'settle', label: 'Settle' },
    { action: 'void', label: 'Void' },
  ];

  /**
   * What is due on a claim: the due fixed when it was settled, or else the figure its person's last
   * statement bound it to, or else its amount at the rate the
   * person's grade has in force on the claim's date (n/a when it is dated before every rate).
   */
  protected dueOf(claim: ClaimView): string {
    const figure = claimDueCents(claim, this.rates(), this.grade(), cents(this.session.floor()));
    return figure === null ? NO_RATE : money(figure);
  }

  /** A claim's due-by: its date plus the sheet's terms. */
  protected dueByOf(claim: ClaimView): string {
    return dueBy(claim, this.session.terms());
  }

  /** Whether a claim is OPEN and due by a date before the sheet's today. */
  protected overdueOf(claim: ClaimView): boolean {
    return overdue(claim, this.session.terms(), this.session.today() ?? '');
  }

  /** The name of the period a claim's date falls in; empty when it falls in none. */
  protected periodOf(claim: ClaimView): string {
    return periodOn(this.periods(), claim.date)?.name ?? '';
  }

  protected value(event: Event): string {
    return (event.target as HTMLInputElement).value;
  }

  /**
   * Open a claim's editor: the form takes its values. Only a DRAFT claim can be edited; any other is
   * refused with an error on its row (to change an OPEN claim, void it and add a new one), as is one
   * dated in a closed period.
   */
  protected open(claim: ClaimView): void {
    this.claimError.set(null);
    if (claim.status !== 'DRAFT') {
      this.reset();
      this.claimError.set({
        id: claim.id,
        message: `A ${claim.status} claim cannot be edited; void it and add a new one.`,
      });
      return;
    }
    const period = periodOn(this.periods(), claim.date);
    if (period?.closed) {
      this.reset();
      this.claimError.set({ id: claim.id, message: `Period ${period.name} is closed, so its claims cannot be edited.` });
      return;
    }
    this.editing.set(claim.id);
    this.amount.set(claim.amount);
    this.date.set(claim.date);
    this.note.set(claim.note);
    this.error.set(null);
  }

  /** Move a claim's status; a move its status does not allow is refused with an error on its row. */
  protected async act(claim: ClaimView, action: ClaimAction): Promise<void> {
    this.claimError.set(null);
    const sheet = this.session.sheet();
    if (!sheet) return;
    try {
      this.saved.emit(await this.api.act(sheet, claim.id, action));
    } catch (e) {
      const own = action === 'settle' && claim.status === 'OPEN' && claim.openedBy === this.session.user()?.trim();
      const overLimit = action === 'settle' && e instanceof HttpErrorResponse && e.status === 403;
      this.claimError.set({
        id: claim.id,
        message: own
          ? 'You opened this claim, so someone else must settle it.'
          : overLimit
            ? 'Its due is above the clerk limit, so a steward must settle it.'
            : `A ${claim.status} claim cannot be ${PAST[action]}.`,
      });
    }
  }

export class People {
  private readonly session = inject(Session);
  private readonly api = inject(PeopleApi);
  private readonly claimsApi = inject(ClaimsApi);
  private readonly ratesApi = inject(RatesApi);
  private readonly periodsApi = inject(PeriodsApi);

  protected readonly grades = GRADES;
  protected readonly people = signal<PersonView[]>([]);
  /** Whether retired people are listed; off when the screen opens, and kept across sheet loads. */
  protected readonly showRetired = signal(false);
  /** The people listed: everyone, or only those not retired unless retired people are shown. */
  protected readonly shownPeople = computed(() =>
    this.showRetired() ? this.people() : this.people().filter((p) => p.retiredFrom === null),
  );
  /** The retire-from date typed on each person's row, by person id; none means the sheet's today. */
  protected readonly retireDates = new Map<number, string>();
  /** The sheet's claims, newest first. */
  protected readonly claims = signal<ClaimView[]>([]);
  private readonly byPerson = computed(() => {
    const map = new Map<number, ClaimView[]>();
    for (const c of this.claims()) map.set(c.personId, [...(map.get(c.personId) ?? []), c]);
    return map;
  });
  /** The sheet's rates, each grade's by from-date; a grade with no rate is not listed. */
  protected readonly rates = signal<RateView[]>([]);
  /** The sheet's periods by from-date. */
  protected readonly periods = signal<PeriodView[]>([]);
  /**
   * Each period's due-total by period id: the sum of the due figures of the OPEN and SETTLED claims
   * dated in it, each at its own person's grade (a claim with no figure adds nothing), leaving out the
   * OPEN claims of anyone on hold.
   */
  protected readonly periodDueTotals = computed(() => {
    const totals = new Map<number, number>(this.periods().map((p) => [p.id, 0]));
    const byId = new Map(this.people().map((p) => [p.id, p]));
    for (const c of this.claims()) {
      const period = periodOn(this.periods(), c.date);
      const person = byId.get(c.personId);
      if (!period || !person || !countsLive(c, person)) continue;
      totals.set(period.id, totals.get(period.id)! + (claimDueCents(c, this.rates(), person.grade, this.floorCents()) ?? 0));
    }
    return new Map([...totals].map(([id, total]) => [id, money(total)]));
  });
  /** The sheet's floor in whole cents: a claim's live due is at least it. */
  private readonly floorCents = computed(() => cents(this.session.floor()));
  /** The sheet's today, on which each grade's rate in force is read. */
  protected readonly today = computed(() => this.session.today() ?? '');
  protected readonly claimedTotal = computed(() =>
    money(this.people().reduce((sum, p) => sum + this.claimedCents(p.id), 0)),
  );
  /** Everyone's due-total added up, skipping those shown as n/a. */
  protected readonly dueTotal = computed(() =>
    money(
      this.people().reduce((sum, p) => sum + (this.dueTotalCents(p) ?? 0), 0),
    ),
  );
  /** How many overdue claims count in the live totals, across everyone. */
  protected readonly overdueCount = computed(() =>
    this.people().reduce((sum, p) => sum + this.overdueOf(p.id).length, 0),
  );
  /** The due of everyone's counting overdue claims added up. */
  protected readonly overdueTotal = computed(() =>
    money(this.people().reduce((sum, p) => sum + this.overdueCents(p), 0)),
  );
  protected readonly name = signal('');
  protected readonly grade = signal<Grade>('A');
  /** The id of the person open in the form, or null when the form adds a new person. */
  protected readonly editing = signal<number | null>(null);
  /** The version of the person open in the form, as it was loaded. */
  private readonly version = signal(0);
  protected readonly error = signal<string | null>(null);
  /** The refusal of the last action taken on a person's row, shown on that row. */
  protected readonly personError = signal<{ id: number; message: string } | null>(null);
  /** A submit is waiting for its answer: a second submit meanwhile is ignored. */
  private busy = false;

  constructor() {
    // Every sheet load re-reads the sheet's people from the store.
    effect(() => {
      const sheet = this.session.sheet();
      this.session.loads();
      untracked(() => {
        this.people.set([]);
        this.claims.set([]);
        this.rates.set([]);
        this.periods.set([]);
        this.reset();
        this.personError.set(null);
        this.retireDates.clear();
        if (sheet) void this.reload(sheet);
      });
    });
  }

  protected claimsOf(personId: number): ClaimView[] {
    return this.byPerson().get(personId) ?? [];
  }

  /** A person's claims that count in the live totals (see countsLive). */
  private countingOf(personId: number): ClaimView[] {
    const person = this.people().find((p) => p.id === personId);
    return person ? this.claimsOf(personId).filter((c) => countsLive(c, person)) : [];
  }

  /** What a person has claimed: the sum of their OPEN and SETTLED claims' amounts (see countsLive). */
  protected claimed(personId: number): string {
    return money(this.claimedCents(personId));
  }

  private claimedCents(personId: number): number {
    return this.countingOf(personId).reduce((sum, c) => sum + cents(c.amount), 0);
  }

  /** A person's overdue claims that count in the live totals (see countsLive). */
  protected overdueOf(personId: number): ClaimView[] {
    return this.countingOf(personId).filter((c) => overdue(c, this.session.terms(), this.today()));
  }

  /** The due of a person's counting overdue claims added up (a claim with no figure adds nothing). */
  protected overdueTotalOf(person: PersonView): string {
    return money(this.overdueCents(person));
  }

  private overdueCents(person: PersonView): number {
    return this.overdueOf(person.id).reduce(
      (sum, c) => sum + (claimDueCents(c, this.rates(), person.grade, this.floorCents()) ?? 0),
      0,
    );
  }

  /** The rate a grade has in force on the sheet's today (a two-decimal percent), or null when it has none. */
  protected pctOf(grade: Grade): string | null {
    return rateOn(this.rates(), grade, this.today());
  }

  /** A person's due-total: the sum of their counting claims' due figures, or n/a (see dueTotalCents). */
  protected dueTotalOf(person: PersonView): string {
    const total = this.dueTotalCents(person);
    return total === null ? NO_RATE : money(total);
  }

  /**
   * A person's due-total in whole cents: the sum of the due figures of their OPEN and SETTLED claims
   * (0 with none; see countsLive). Null (n/a) when their grade has no rate on the sheet's today, unless a settled
   * or stated claim keeps a fixed figure: then it is the sum of the figures there are.
   */
  private dueTotalCents(person: PersonView): number | null {
    const counting = this.countingOf(person.id);
    const fixed = (c: ClaimView) => c.settledDue !== null || (c.stated && c.statedDue !== null);
    if (this.pctOf(person.grade) === null && !counting.some(fixed)) return null;
import { HttpClient } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';

export interface SheetView {
  id: string;
  /** The sheet's today (yyyy-mm-dd): every date-dependent decision and default date uses it. */
  today: string;
  /** The sheet's floor with two decimals: a claim's live due is at least it. */
  floor: string;
  /** The sheet's terms in days: a claim is due by its date plus them. */
  terms: number;
}

// The signed-in user (a typed name, no password) and the active sheet. Everything else in the
// app is kept per sheet, so features read the active sheet id from here.
@Injectable({ providedIn: 'root' })
export class Session {
  private readonly http = inject(HttpClient);

  readonly user = signal<string | null>(null);
  readonly sheet = signal<string | null>(null);
  /** The active sheet's today; features use it, never the real clock. */
  readonly today = signal<string | null>(null);
  /** The active sheet's floor with two decimals: a claim's live due is at least it. */
  readonly floor = signal('1.00');
  /** The active sheet's terms in days: a claim is due by its date plus them. */
  readonly terms = signal(14);
  /** Counts sheet loads, so features re-read the store even when the same id is loaded again. */
  readonly loads = signal(0);

  signIn(name: string): void {
    this.user.set(name);
  }

  /** Load a sheet by id from the store; an id never used before starts an empty sheet. */
  async loadSheet(id: string): Promise<void> {
    const view = await firstValueFrom(
      this.http.post<SheetView>(`/api/sheets/${encodeURIComponent(id)}/load`, null),
    );
    this.show(view);
    this.loads.update((n) => n + 1);
  }

  /** Change the active sheet's today in the store. */
  async setToday(date: string): Promise<void> {
    const id = this.sheet();
    if (!id) throw new Error('No sheet is loaded.');
    const view = await firstValueFrom(
      this.http.put<SheetView>(`/api/sheets/${encodeURIComponent(id)}/today`, { today: date }),
    );
    this.show(view);
  }

  private show(view: SheetView): void {
    this.sheet.set(view.id);
    this.today.set(view.today);
    this.floor.set(view.floor);
    this.terms.set(view.terms);
  }
}

